    # Initial placement of knights
    knights = []
    for i in range(n):
        knights.append((i, 0))

    # Function to check if a cell is under attack by at least 4 knights
    def is_under_attack(x, y, knights):
        count = 0
        for kx, ky in knights:
            if abs(x - kx) + abs(y - ky) == 3:
                count += 1
        return count >= 4

    # Process to add new knights
    while True:
        new_knights = []
        for x in range(-10**9, 10**9 + 1):
            for y in range(-10**9, 10**9 + 1):
                if (x, y) not in knights and is_under_attack(x, y, knights):
                    new_knights.append((x, y))
        if not new_knights:
            break
        knights.extend(new_knights)

    # Output the final placement of knights
    for x, y in knights:
